-- ═══════════════════════════════════════════════════════════════════════
-- MIGRATION LEDGER BASELINE
-- Generated by backend/scripts/generate-migration-baseline.js on 2026-09-10T02:44:39.425Z
--
-- This RECORDS migrations as applied. It does NOT run them. Paste it into the
-- Supabase SQL editor once, on a database whose schema is already current.
--
-- Marks applied : 122 migrations, through 20260910010000
-- Leaves pending: 1 (20260911000000)
--
-- AFTERWARDS, PROVE IT: run `supabase db diff` (or
-- `node backend/scripts/audit-schema.js`). A clean result means the baseline was
-- honest. A dirty one names exactly what was never applied — apply that by hand,
-- because the CLI will now skip it forever.
-- ═══════════════════════════════════════════════════════════════════════

BEGIN;

-- The ledger lives in its own schema and may not exist on a database that has
-- never been touched by the CLI. Creating it here is what makes this safe to run
-- before the first `db push` rather than after it.
CREATE SCHEMA IF NOT EXISTS supabase_migrations;

CREATE TABLE IF NOT EXISTS supabase_migrations.schema_migrations (
  version    TEXT PRIMARY KEY,
  statements TEXT[],
  name       TEXT
);

-- `statements` is left NULL on purpose: it is the CLI's record of what it ran,
-- and it ran nothing. Filling it with the file contents would claim otherwise.
--
-- ON CONFLICT DO NOTHING so this is re-runnable and so it can never overwrite a
-- row the CLI wrote itself.
ON CONFLICT (version) DO NOTHING;

-- What the ledger looks like afterwards.
SELECT count(*) AS recorded, min(version) AS oldest, max(version) AS newest
FROM supabase_migrations.schema_migrations;

COMMIT;
